    companion object {
        fun forHarness(harness: String?): BrandMark = when (harness) {
            "codex" -> OPENAI
            "cursor" -> CURSOR
            "devin" -> DEVIN
            "grok" -> GROK
            "hermes" -> HERMES
            "pi" -> PI
            "opencode" -> OPENCODE
            "antigravity" -> ANTIGRAVITY
            // claude-code + mock share the mark, like the desktop.
            else -> CLAUDE
        }

    }

    /** The brand's own color; null for black-or-white marks, which take the caller's tint. */
    val color: Color?
        get() = when (this) {
            CLAUDE -> Color(0xFFD97757)
            DEVIN -> Color(0xFF0294DE)
            ANTIGRAVITY -> Color(0xFF3186FF)
            GEMINI -> Color(0xFF3186FF)
            DEEPSEEK -> Color(0xFF4D6BFE)
            QWEN -> Color(0xFF6F69F7)
            MINIMAX -> Color(0xFFF0365E)
            MISTRAL -> Color(0xFFFA500F)
            // The two greens are darkened from the brand values to hold 3:1 on white.
            NVIDIA -> Color(0xFF5E9400)
            META -> Color(0xFF0081FB)
            LONGCAT -> Color(0xFF1A9E3A)
            else -> null
        }
}
private val parsed = HashMap<BrandMark, androidx.compose.ui.graphics.Path>()

private fun BrandMark.path(): androidx.compose.ui.graphics.Path = parsed.getOrPut(this) {
    androidx.compose.ui.graphics.vector.PathParser().parsePathString(pathData).toPath().also {
        it.fillType = if (evenOdd) androidx.compose.ui.graphics.PathFillType.EvenOdd else androidx.compose.ui.graphics.PathFillType.NonZero
    }
}

/** A harness mark, aspect-fit and centered, in its brand color when it has one. */
@androidx.compose.runtime.Composable
fun HarnessMark(harness: String?, size: androidx.compose.ui.unit.Dp, modifier: androidx.compose.ui.Modifier = androidx.compose.ui.Modifier, tint: Color = androidx.compose.material3.LocalContentColor.current) {
    val mark = BrandMark.forHarness(harness)
    MarkGlyph(mark, mark.color ?: tint, size, modifier)
}

/** A model vendor's mark; [ModelVendor.OTHER] falls back to the harness mark. */
@androidx.compose.runtime.Composable
fun VendorMark(vendor: ModelVendor, harness: String?, size: androidx.compose.ui.unit.Dp, tint: Color = androidx.compose.material3.LocalContentColor.current) {
    val mark = vendor.mark ?: return HarnessMark(harness, size, tint = tint)
    MarkGlyph(mark, mark.color ?: tint, size, androidx.compose.ui.Modifier)
}

/** The mark for a chosen model: its vendor's, else its harness's. */
@androidx.compose.runtime.Composable
fun ModelMark(model: String?, harness: String?, size: androidx.compose.ui.unit.Dp) =
    VendorMark(model?.let { ModelVendor.of(it, harness) } ?: ModelVendor.OTHER, harness, size)

@androidx.compose.runtime.Composable
private fun MarkGlyph(mark: BrandMark, color: Color, size: androidx.compose.ui.unit.Dp, modifier: androidx.compose.ui.Modifier) {
    androidx.compose.foundation.Canvas(modifier.then(androidx.compose.ui.Modifier.size(size))) {
        val scale = minOf(this.size.width / mark.width, this.size.height / mark.height)
        val dx = (this.size.width - mark.width * scale) / 2
        val dy = (this.size.height - mark.height * scale) / 2
        translate(dx, dy) {
            scale(scale, pivot = androidx.compose.ui.geometry.Offset.Zero) {
                drawPath(mark.path(), color)
            }
        }
    }
}

/**
 * Who makes a model, read from its id; a gateway like opencode's Zen serves
 * many vendors under one provider. Order is the picker's section order.
 */
enum class ModelVendor(val title: String, val mark: BrandMark?, private val prefixes: List<String>) {
    // Cursor names Claude models by family alone (`sonnet-4.5`).
    ANTHROPIC("Anthropic", BrandMark.CLAUDE, listOf("claude", "opus", "sonnet", "haiku", "fable")),
    OPENAI("OpenAI", BrandMark.OPENAI, listOf("gpt", "codex", "o1", "o3", "o4", "chatgpt")),
    GOOGLE("Google", BrandMark.GEMINI, listOf("gemini", "gemma")),
    XAI("xAI", BrandMark.GROK, listOf("grok")),
    DEEPSEEK("DeepSeek", BrandMark.DEEPSEEK, listOf("deepseek")),
    QWEN("Qwen", BrandMark.QWEN, listOf("qwen", "qwq")),
    MOONSHOT("Moonshot AI", BrandMark.KIMI, listOf("kimi", "moonshot")),
    ZAI("Z.ai", BrandMark.ZAI, listOf("glm")),
    MINIMAX("MiniMax", BrandMark.MINIMAX, listOf("minimax")),
    MISTRAL("Mistral", BrandMark.MISTRAL, listOf("mistral", "codestral", "devstral", "magistral", "ministral")),
    META("Meta", BrandMark.META, listOf("llama", "muse")),
    NVIDIA("NVIDIA", BrandMark.NVIDIA, listOf("nemotron")),
    XIAOMI("Xiaomi", BrandMark.XIAOMI, listOf("mimo")),
    MEITUAN("Meituan", BrandMark.LONGCAT, listOf("longcat")),
    OTHER("Other", null, emptyList());

    companion object {
        fun of(modelId: String, harness: String? = null): ModelVendor {
            // A first-party harness only runs its maker's models, whatever the
            // id (`default`, `opus`).
            when (harness) {
                "claude-code", "mock" -> return ANTHROPIC
                "codex" -> return OPENAI
            }
            val name = modelId.substringAfterLast('/').lowercase()
            // NVIDIA's Llama Nemotron family starts with `llama`.
            if ("nemotron" in name) return NVIDIA
            return entries.firstOrNull { v -> v.prefixes.any { name.startsWith(it) } } ?: OTHER
        }
    }
}
